  sealed class ServerRow {public ServerNode Node{get;set;}public string Name{get{return ServerIdentity.Display(Node.Name);}}public string Transport{get{return Node.TransportLabel;}}public string Host{get{return VkTurnOptions.Value(Node.TurnPreferences,"server",Node.Host);}}public string Ping{get{return Node.Latency<0?"—":Node.Latency+" мс";}}public string Group{get{return Node.Source??"";}}}
  bool serverProbeRunning;DateTime lastServerProbe;
  async Task ProbeServers(){if(serverProbeRunning)return;serverProbeRunning=true;try{status.Text="Проверяем задержку серверов…";var probed=session.State;await session.ProbeServers();if(closing||!Object.ReferenceEquals(probed,session.State))return;lastServerProbe=DateTime.UtcNow;if(current=="Серверы")RefreshAfterOperation("Серверы");}finally{serverProbeRunning=false;}}
  UIElement VpnServers(){
   var panel=new DockPanel();var header=new StackPanel{Margin=new Thickness(0,0,0,10)};header.Children.Add(AutoSelectSettings());var import=new TextBox{Name="serverImport",ToolTip="Ссылка сервера, HTTPS-подписка или конфигурация",MinHeight=34,Margin=new Thickness(0)};var importRow=new DockPanel{Margin=new Thickness(0,0,0,10)};var importActions=CompactTools(AsyncButton("Добавить",()=>ImportServerText(import.Text)),Button("Взять файл",()=>{var picker=new Microsoft.Win32.OpenFileDialog{Filter="Конфигурации|*.txt;*.json;*.conf|Все файлы|*.*"};if(picker.ShowDialog(this)==true)import.Text=File.ReadAllText(picker.FileName);}));importActions.Margin=new Thickness(12,0,0,0);DockPanel.SetDock(importActions,Dock.Right);importRow.Children.Add(importActions);importRow.Children.Add(import);header.Children.Add(Field("Сервер или подписка · ссылка / конфигурация",importRow));DockPanel.SetDock(header,Dock.Top);panel.Children.Add(header);
   var rows=session.State.Servers.Where(n=>!WarpPicker.IsWarp(n)).Select(n=>new ServerRow{Node=n}).ToArray();var view=new System.Windows.Data.ListCollectionView(rows);view.GroupDescriptions.Add(new System.Windows.Data.PropertyGroupDescription("Group"));var table=new DataGrid{Name="serverGrid",ItemsSource=view,SelectionMode=DataGridSelectionMode.Extended,RowHeight=38,EnableColumnVirtualization=false,HorizontalContentAlignment=HorizontalAlignment.Stretch};System.Windows.Controls.VirtualizingPanel.SetIsVirtualizingWhenGrouping(table,true);var groupFactory=new FrameworkElementFactory(typeof(CellPresenter));groupFactory.SetValue(CellPresenter.CreateProperty,new Func<object,UIElement>(o=>{var group=(System.Windows.Data.CollectionViewGroup)o;string source=Convert.ToString(group.Name);Uri uri;return new TextBlock{Text=String.IsNullOrWhiteSpace(source)?"Добавлены вручную":Uri.TryCreate(source,UriKind.Absolute,out uri)&&!String.IsNullOrWhiteSpace(uri.Host)?"Подписка · "+uri.Host:"Импорт из файла",Margin=new Thickness(8,12,0,6),Foreground=Brush("#4EE7FC")};}));table.GroupStyle.Add(new GroupStyle{HeaderTemplate=new DataTemplate{VisualTree=groupFactory}});
   table.Columns.Add(CellColumn("Сервер",2.8,o=>{var r=(ServerRow)o;var line=new DockPanel();var flag=new Image{Source=FlagImage(r.Node.Name),Width=24,Height=16,Margin=new Thickness(0,0,8,0)};DockPanel.SetDock(flag,Dock.Left);line.Children.Add(flag);line.Children.Add(CellText(r.Name));return line;}));table.Columns.Add(new DataGridTextColumn{Header="Протокол / транспорт",Binding=new System.Windows.Data.Binding("Transport"),Width=new DataGridLength(2.1,DataGridLengthUnitType.Star)});table.Columns.Add(new DataGridTextColumn{Header="Адрес",Binding=new System.Windows.Data.Binding("Host"),Width=new DataGridLength(1.5,DataGridLengthUnitType.Star)});table.Columns.Add(new DataGridTextColumn{Header="Задержка",Binding=new System.Windows.Data.Binding("Ping"),Width=94});table.Columns[0].MinWidth=150;table.Columns[1].MinWidth=180;table.Columns[2].MinWidth=120;table.SelectedItem=rows.FirstOrDefault(r=>r.Node.Id==session.State.SelectedServerId);
   Func<Task> choose=async()=>{var row=table.SelectedItem as ServerRow;if(row==null)throw new InvalidOperationException("Выберите сервер");if(!CompleteCsqttPasswords(new[]{row.Node},false))return;if(!session.Core.HasEngine(row.Node)&&!await DownloadCsqttRequirements(new[]{row.Node},false))return;if(!session.Core.HasEngine(row.Node)){updatesType=1;RefreshAfterOperation("Обновления");status.Text="Для сервера "+row.Name+" сначала скачайте движок.";return;}await session.ChangeConfiguration(()=>{session.State.SelectedServerId=row.Node.Id;session.State.AutoSelect=false;});status.Text="Выбран: "+row.Name;};table.MouseDoubleClick+=async(s,e)=>await Run(choose);
   var icons=CellColumn("",1,o=>{var row=(ServerRow)o;var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};
    actions.Children.Add(IconButton("ping","Проверить пинг",()=>ProbeServer(row.Node,table)));
    if(new[]{"csqtt","wdtt","qwdtt"}.Contains(row.Node.Protocol))actions.Children.Add(IconButton("edit","Параметры VK TURN",()=>{QueueVkTurnEditor(row.Node);return Task.FromResult(0);}));
    actions.Children.Add(IconButton("copy","Копировать подключение",()=>CopyText(VkTurnOptions.Share(row.Node,root))));
    actions.Children.Add(IconButton("remove","Удалить подключение",async()=>{if(!Confirm("Удалить «"+row.Name+"»?","Серверы"))return;await session.ChangeConfiguration(()=>{session.State.Servers.Remove(row.Node);if(session.State.SelectedServerId==row.Node.Id)session.State.SelectedServerId="";});RefreshAfterOperation("Серверы");}));return actions;});icons.Width=IconCellWidth(4);icons.MinWidth=IconCellWidth(4);table.Columns.Add(icons);
   var chooseButton=AsyncButton("Выбрать подключение",choose);chooseButton.MinWidth=180;var pingAll=AsyncButton("Пинговать все",ProbeServers);pingAll.Name="pingAllServers";pingAll.MinWidth=160;var lower=CompactTools(chooseButton,pingAll);lower.Margin=new Thickness(0,12,0,0);table.Margin=new Thickness(0,0,0,8);DockPanel.SetDock(lower,Dock.Bottom);panel.Children.Add(lower);panel.Children.Add(table);if(!diagnostic&&rows.Length>0&&DateTime.UtcNow-lastServerProbe>TimeSpan.FromMinutes(5))Dispatcher.BeginInvoke(new Action(()=>LoadBasicJournal(ProbeServers)),System.Windows.Threading.DispatcherPriority.Background);return panel;
  }
  async Task UpdateSubscriptions(){var urls=(session.State.SubscriptionUrls??new List<string>()).Concat(new[]{session.State.SubscriptionUrl}).Where(u=>!String.IsNullOrWhiteSpace(u)).Distinct().ToArray();if(urls.Length==0)throw new InvalidOperationException("Нет подписок");var texts=await Task.WhenAll(urls.Select(session.Core.DownloadTextAsync));foreach(string content in texts)CsqttGenerations.ValidateBatch(content);var imports=texts.Select(t=>Links.Read(t).ToList()).ToArray();if(imports.Any(n=>n.Count==0))throw new FormatException("Подписка не содержит серверы");for(int i=0;i<urls.Length;i++)SubscriptionMerge.InheritCsqttGenerations(imports[i],session.State.Servers,urls[i]);if(!ChooseCsqttGenerations(imports.SelectMany(n=>n)))return;if(!await DownloadCsqttRequirements(imports.SelectMany(n=>n),true))return;await session.ChangeConfiguration(()=>{for(int i=0;i<urls.Length;i++)SubscriptionMerge.Apply(session.State,imports[i],urls[i]);});await session.ProbeServers();lastServerProbe=DateTime.UtcNow;RefreshAfterOperation("Серверы");}
  async Task ProbeServer(ServerNode node,DataGrid table){await session.ProbeServer(node);if(!closing&&table.IsLoaded){table.Items.Refresh();status.Text=node.Latency<0?"Сервер не ответил на проверку задержки.":ServerIdentity.Display(node.Name)+": "+node.Latency+" мс";}}
  async Task ImportServerText(string input){
   string text=(input??"").Trim(),source=null;Uri uri;if(Uri.TryCreate(text,UriKind.Absolute,out uri)&&uri.Scheme=="https"){source=text;text=await session.Core.DownloadTextAsync(source);}CsqttGenerations.ValidateBatch(text);var nodes=Links.Read(text).ToList();if(nodes.Count==0)throw new FormatException("В тексте не найдены серверы");if(!ChooseCsqttGenerations(nodes)||!CompleteCsqttPasswords(nodes,true))return;foreach(var node in nodes)session.Core.ValidateImport(node);if(!await DownloadCsqttRequirements(nodes,true))return;await session.ChangeConfiguration(()=>SubscriptionMerge.Apply(session.State,nodes,source));bool missing=nodes.Any(n=>!session.Core.HasEngine(n));RefreshAfterOperation("Серверы");status.Text=missing?"Серверы добавлены. При выборе подключения предложим скачать недостающие компоненты.":"Добавлено серверов: "+nodes.Count;
  }
