   var panel=new DockPanel();var note=Text("Выберите вариант Wardogs. Существующие маршруты не заменяются.");DockPanel.SetDock(note,Dock.Top);panel.Children.Add(note);var table=Table(rows,"Шаблон|Name","Адресов|Addresses","Параметры|State");table.Columns[0].Width=new DataGridLength(2,DataGridLengthUnitType.Star);table.Columns[1].Width=100;table.Columns[2].Width=new DataGridLength(3,DataGridLengthUnitType.Star);table.SelectedIndex=0;
   var add=AsyncButton("Добавить в маршруты",async()=>{var selected=table.SelectedItem as GameTemplateRow;if(selected==null)return;var catalog=await session.Strategies();var pair=selected.Kind=="alt11"?SteamGameTemplates.Wardogs(catalog):selected.Kind=="alternative"?SteamGameTemplates.WardogsAlternative(catalog):SteamGameTemplates.WardogsArchive(catalog);if(session.State.Lists.Any(r=>r.BuiltinPreset==pair.Item2.BuiltinPreset))throw new InvalidOperationException("Этот шаблон уже добавлен. Измените существующий маршрут.");await session.ChangeConfiguration(()=>{session.State.ZapretProfiles.Add(pair.Item1);if(selected.Kind=="arhekog"&&!session.State.Lists.Any(r=>r.BuiltinPreset=="game:wardogs-arhekog-protect"))session.State.Lists.Insert(0,new RouteList{Name="Wardogs arhekog · без подмены",Target="direct",Text=SteamGameTemplates.WardogsArchiveProtected,MatchMode="addresses",BuiltinPreset="game:wardogs-arhekog-protect"});session.State.Lists.Add(pair.Item2);});RegisterHotkeys();RefreshAfterOperation("Маршрутизация");});Accent(add);var actions=Toolbar(add,Button("Назад",()=>Page("Маршрутизация")));DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);panel.Children.Add(table);body.Children.Add(Card(panel));
